#!/usr/bin/env bash
# -*- coding: utf-8 -*-
#
# @file
# @brief Canonical clean-up tool for every artifact generated by `scripts/build.sh`.
# @details Resolves the repository root from its own path, validates the
# required toolchain, resolves the project name from `pyproject.toml`,
# deletes only the generated release artifacts from `dist/` (project sdist,
# project wheel, GNOME extension zip), removes the `build/` directory
# produced by the Python distribution build, removes the `dist/` directory
# when empty after cleanup, and prints a summary listing every removed path.
# Non-generated content inside `dist/` is never deleted. Time complexity
# O(E) over `dist/` entries E; space O(R) for the removed-path summary R.
# @pre `uv` and `find` are available in `PATH`.
# @pre `pyproject.toml` declares `project.name`.
# @post No generated `scripts/build.sh` artifact remains in the repository.
# @return Exit status of the cleanup.
# @retval 0 Every generated artifact was removed or was already absent.
# @retval 1 Toolchain, metadata resolution, or removal failed.
# @retval 2 Unexpected arguments.
# @satisfies PRJ-042
# @satisfies PRJ-043
# @satisfies PRJ-044
# @satisfies PRJ-045
# @satisfies PRJ-046

set -Eeuo pipefail

# var SCRIPT_PATH {string} Absolute path of this script after symlink resolution.
SCRIPT_PATH="$(readlink -f "${BASH_SOURCE[0]}")"
# var SCRIPT_DIR {string} Absolute directory containing this script.
SCRIPT_DIR="$(dirname "$SCRIPT_PATH")"
# var REPO_ROOT {string} Absolute repository root derived from the script path.
REPO_ROOT="$(dirname "$SCRIPT_DIR")"
# var DIST_DIR {string} Canonical release-artifact destination directory cleaned by this script.
DIST_DIR="$REPO_ROOT/dist"
# var BUILD_DIR {string} Python distribution build directory produced by `python -m build`.
BUILD_DIR="$REPO_ROOT/build"
# var EXTENSION_ZIP_NAME {string} Release archive file name of the GNOME extension.
EXTENSION_ZIP_NAME="aibar@aibar.panel.shell-extension.zip"
# var PROJECT_NAME {string} Distribution name resolved from `pyproject.toml`.
PROJECT_NAME=""
# var CURRENT_STAGE {string} Active cleanup phase used by failure diagnostics.
CURRENT_STAGE="initialization"
# var REMOVED_PATHS {string[]} Absolute paths removed by this execution, in removal order.
REMOVED_PATHS=()

## @fn on_error
# @brief Report the failing phase and command of an unexpected failure.
# @details Registered as the ERR trap so `set -Eeuo pipefail` failures name the
# active phase and the exact failing command before the process exits.
# @return {void} Returns only when invoked with a zero exit status.
# @satisfies PRJ-042
on_error() {
  local exit_code=$?
  if [ "$exit_code" -ne 0 ]; then
    printf 'ERROR: command failed (exit %d) during "%s": %s\n' \
      "$exit_code" "$CURRENT_STAGE" "$BASH_COMMAND" >&2
  fi
  exit "$exit_code"
}

trap on_error ERR

## @fn usage
# @brief Print the script usage text to stdout.
# @return {void} No return value.
usage() {
  cat <<'EOF'
Usage: scripts/clean.sh

Removes every artifact generated by scripts/build.sh:
  1. validates the required toolchain (uv, find)
  2. deletes the generated sdist, wheel, and GNOME extension zip from dist/
  3. removes the build/ directory produced by the Python distribution build
  4. removes dist/ when it is empty after cleanup

Non-generated content inside dist/ is never deleted.
EOF
}

## @fn fail
# @brief Abort the cleanup with one diagnostic message.
# @param message {string} Diagnostic text describing the failed requirement.
# @return {void} The function never returns.
# @satisfies PRJ-042
fail() {
  local message="$1"
  printf 'ERROR: %s\n' "$message" >&2
  exit 1
}

## @fn require_tool
# @brief Abort when one required executable is unavailable.
# @details Resolves the executable through `command -v`; a missing executable
# terminates the cleanup before any artifact mutation.
# @param tool_name {string} Executable name validated in `PATH`.
# @return {void} Returns when the executable resolves.
# @satisfies PRJ-045
require_tool() {
  local tool_name="$1"
  if ! command -v "$tool_name" >/dev/null 2>&1; then
    fail "required executable not found in PATH: $tool_name"
  fi
  printf '  tool available: %s\n' "$tool_name"
}

## @fn validate_toolchain
# @brief Validate every executable required to remove generated artifacts.
# @return {void} Returns when the toolchain is complete.
# @satisfies PRJ-045
validate_toolchain() {
  require_tool uv
  require_tool find
}

## @fn load_project_metadata
# @brief Resolve the distribution name from `pyproject.toml`.
# @details Reads the PEP 621 project name through the project environment so
# no duplicated name literal exists outside `pyproject.toml`; the resolved
# name scopes the generated sdist and wheel deletion patterns.
# @return {void} Returns after populating `PROJECT_NAME`.
# @satisfies PRJ-044
load_project_metadata() {
  PROJECT_NAME="$(uv run --locked --project "$REPO_ROOT" python -c '
import pathlib
import sys
import tomllib

data = tomllib.loads(pathlib.Path(sys.argv[1]).read_text(encoding="utf-8"))
print(data["project"]["name"])
' "$REPO_ROOT/pyproject.toml")"
  if [ -z "$PROJECT_NAME" ]; then
    fail "unable to resolve project name from pyproject.toml"
  fi
  printf '  project: %s\n' "$PROJECT_NAME"
}

## @fn is_generated_dist_entry
# @brief Report whether one `dist/` entry is a build-generated artifact.
# @details Generated entries are the project sdist archive, project wheel
# archives, and the GNOME extension zip; every other entry is foreign and
# MUST be preserved.
# @param entry_path {string} Absolute or repository-relative `dist/` entry path.
# @return {int} 0 when the entry matches a generated artifact pattern.
# @satisfies PRJ-044
is_generated_dist_entry() {
  local entry_path="$1"
  local entry_name
  entry_name="$(basename "$entry_path")"
  case "$entry_name" in
    "${PROJECT_NAME}-"*.tar.gz) return 0 ;;
    "${PROJECT_NAME}-"*.whl) return 0 ;;
    "$EXTENSION_ZIP_NAME") return 0 ;;
    *) return 1 ;;
  esac
}

## @fn remove_generated_dist_artifacts
# @brief Delete every generated release artifact from `dist/`.
# @details Iterates `dist/` top-level regular files and deletes only entries
# accepted by `is_generated_dist_entry`, recording each removed path in
# `REMOVED_PATHS`; foreign entries are preserved untouched.
# @return {void} Returns after targeted removal.
# @satisfies PRJ-042
# @satisfies PRJ-044
remove_generated_dist_artifacts() {
  if [ ! -d "$DIST_DIR" ]; then
    printf '  no dist/ directory to clean\n'
    return 0
  fi
  local entry
  while IFS= read -r entry; do
    if [ -n "$entry" ] && is_generated_dist_entry "$entry"; then
      rm -f -- "$entry"
      REMOVED_PATHS+=("$entry")
      printf '  removed: %s\n' "$entry"
    fi
  done < <(find "$DIST_DIR" -mindepth 1 -maxdepth 1 -type f -print)
}

## @fn remove_build_dir
# @brief Remove the `build/` directory produced by the Python distribution build.
# @details Deletes the setuptools build byproduct tree when present; an absent
# `build/` directory is reported as already clean.
# @return {void} Returns after removal or when nothing exists.
# @satisfies PRJ-042
remove_build_dir() {
  if [ -d "$BUILD_DIR" ]; then
    rm -rf -- "$BUILD_DIR"
    REMOVED_PATHS+=("$BUILD_DIR")
    printf '  removed: %s\n' "$BUILD_DIR"
  else
    printf '  no build/ directory to clean\n'
  fi
}

## @fn remove_empty_dist_dir
# @brief Remove the `dist/` directory when no entries remain after cleanup.
# @details Uses `rmdir` so removal succeeds only on an empty directory; any
# preserved foreign entry keeps `dist/` in place.
# @return {void} Returns after removal or when `dist/` is absent or non-empty.
# @satisfies PRJ-046
remove_empty_dist_dir() {
  if [ -d "$DIST_DIR" ] && [ -z "$(find "$DIST_DIR" -mindepth 1 -maxdepth 1 -print -quit)" ]; then
    rmdir -- "$DIST_DIR"
    REMOVED_PATHS+=("$DIST_DIR")
    printf '  removed empty directory: %s\n' "$DIST_DIR"
  fi
}

## @fn print_clean_summary
# @brief Print the summary listing every path removed by this execution.
# @details Emits one deterministic line per removed path in removal order, or
# an explicit already-clean message when no generated artifact existed.
# @return {void} No return value.
# @satisfies PRJ-046
print_clean_summary() {
  printf '\n==> clean completed\n'
  if [ "${#REMOVED_PATHS[@]}" -eq 0 ]; then
    printf 'no build artifacts found; repository already clean\n'
  else
    printf 'removed %d path(s):\n' "${#REMOVED_PATHS[@]}"
    printf '  %s\n' "${REMOVED_PATHS[@]}"
  fi
}

# Argument parsing: this script accepts only the help flags.
for arg in "$@"; do
  case "$arg" in
    -h | --help)
      usage
      exit 0
      ;;
    *)
      printf 'ERROR: unknown argument: %s\n' "$arg" >&2
      usage >&2
      exit 2
      ;;
  esac
done

CURRENT_STAGE="toolchain validation"
validate_toolchain

CURRENT_STAGE="project metadata resolution"
load_project_metadata

CURRENT_STAGE="dist artifact cleanup"
remove_generated_dist_artifacts

CURRENT_STAGE="build directory cleanup"
remove_build_dir

CURRENT_STAGE="empty dist directory cleanup"
remove_empty_dist_dir

CURRENT_STAGE="clean summary"
print_clean_summary

CURRENT_STAGE="completed"
